use std::io::{Read, Write, BufRead, BufReader};
use std::net::TcpStream;
use std::collections::HashMap;

/// Cloud SDK HTTP client for forwarding user upload requests to internal storage service.
/// Handles chunked transfer encoding from untrusted sources.

const INTERNAL_STORAGE_HOST: &str = "storage-internal.cluster.local:8080";
const MAX_UPLOAD_SIZE: u64 = 50 * 1024 * 1024; // 50MB

#[derive(Debug, Clone)]
pub struct UploadRequest {
    pub method: String,
    pub path: String,
    pub headers: HashMap<String, String>,
    pub body: Vec<u8>,
}

#[derive(Debug)]
pub enum ParseError {
    InvalidRequest,
    TooLarge,
    IoError(std::io::Error),
    AmbiguousLength,
}

/// Parses Content-Length value, handling potential whitespace and multiple values.
/// Per RFC 7230, if multiple Content-Length values are present, they must all be equal.
fn parse_content_length(header_value: &str) -> Result<u64, ParseError> {
    let values: Vec<&str> = header_value.split(',').collect();
    let mut result: Option<u64> = None;
    for val in values {
        let trimmed = val.trim();
        let parsed = trimmed.parse::<u64>().map_err(|_| ParseError::InvalidRequest)?;
        match result {
            None => result = Some(parsed),
            Some(prev) => {
                if prev != parsed {
                    return Err(ParseError::InvalidRequest);
                }
            }
        }
    }
    result.ok_or(ParseError::InvalidRequest)
}

/// Determines the effective body length for the forwarded request.
/// Implements strict validation: rejects requests with both TE and CL (RFC 7230 Section 3.3.3)
fn determine_body_length(headers: &HashMap<String, String>) -> Result<BodyLength, ParseError> {
    // Check for Transfer-Encoding first (higher priority per RFC)
    let has_te = headers.keys().any(|k| k.to_ascii_lowercase() == "transfer-encoding");
    let has_cl = headers.keys().any(|k| k.to_ascii_lowercase() == "content-length");

    if has_te && has_cl {
        // SECURITY: Reject ambiguous requests entirely to prevent smuggling
        return Err(ParseError::AmbiguousLength);
    }

    if has_te {
        return Ok(BodyLength::Chunked);
    }

    if has_cl {
        let cl_value = headers.iter()
            .find(|(k, _)| k.to_ascii_lowercase() == "content-length")
            .map(|(_, v)| v.as_str())
            .unwrap();
        let length = parse_content_length(cl_value)?;
        if length > MAX_UPLOAD_SIZE {
            return Err(ParseError::TooLarge);
        }
        return Ok(BodyLength::Fixed(length));
    }

    Ok(BodyLength::Fixed(0))
}

#[derive(Debug)]
enum BodyLength {
    Fixed(u64),
    Chunked,
}

/// Reads a chunked body from the input stream.
/// Validates chunk sizes and enforces maximum upload size.
fn read_chunked_body(reader: &mut BufReader<&[u8]>) -> Result<Vec<u8>, ParseError> {
    let mut body = Vec::new();
    loop {
        let mut size_line = String::new();
        reader.read_line(&mut size_line).map_err(ParseError::IoError)?;
        let size_str = size_line.trim_end_matches(|c| c == '\r' || c == '\n');
        // Handle chunk extensions by splitting on ';'
        let size_hex = size_str.split(';').next().unwrap_or("").trim();
        let chunk_size = u64::from_str_radix(size_hex, 16)
            .map_err(|_| ParseError::InvalidRequest)?;

        if chunk_size == 0 {
            // Read trailing CRLF
            let mut trailer = String::new();
            reader.read_line(&mut trailer).map_err(ParseError::IoError)?;
            break;
        }

        if body.len() as u64 + chunk_size > MAX_UPLOAD_SIZE {
            return Err(ParseError::TooLarge);
        }

        let mut chunk = vec![0u8; chunk_size as usize];
        reader.read_exact(&mut chunk).map_err(ParseError::IoError)?;
        body.extend_from_slice(&chunk);

        // Read CRLF after chunk data
        let mut crlf = [0u8; 2];
        reader.read_exact(&mut crlf).map_err(ParseError::IoError)?;
    }
    Ok(body)
}

/// Constructs the forwarded HTTP request to internal storage.
/// Normalizes headers and rebuilds the request in a canonical form.
fn build_forwarded_request(req: &UploadRequest) -> Vec<u8> {
    let mut output = Vec::new();
    write!(output, "{} {} HTTP/1.1\r\n", req.method, req.path).unwrap();
    write!(output, "Host: {}\r\n", INTERNAL_STORAGE_HOST).unwrap();

    // Forward safe headers, skip hop-by-hop headers
    let hop_by_hop = ["connection", "keep-alive", "proxy-authenticate",
                      "proxy-authorization", "te", "trailers", "upgrade"];

    for (key, value) in &req.headers {
        let lower = key.to_ascii_lowercase();
        if lower == "host" || hop_by_hop.contains(&lower.as_str()) {
            continue;
        }
        // Skip transfer-encoding; we'll send with Content-Length
        if lower == "transfer-encoding" {
            continue;
        }
        // Skip original content-length; we'll recalculate
        if lower == "content-length" {
            continue;
        }
        write!(output, "{}: {}\r\n", key, value).unwrap();
    }

    write!(output, "Content-Length: {}\r\n", req.body.len()).unwrap();
    write!(output, "\r\n").unwrap();
    output.extend_from_slice(&req.body);
    output
}

/// Main entry point: parses an incoming upload request and forwards it to storage.
/// This function is called by the gateway when processing user uploads.
/// Only processes a SINGLE request per invocation to prevent smuggling.
pub fn process_upload(raw_request: &[u8]) -> Result<Vec<u8>, ParseError> {
    let mut reader = BufReader::new(raw_request);

    // Parse request line
    let mut request_line = String::new();
    reader.read_line(&mut request_line).map_err(ParseError::IoError)?;
    let parts: Vec<&str> = request_line.trim().splitn(3, ' ').collect();
    if parts.len() != 3 {
        return Err(ParseError::InvalidRequest);
    }
    let method = parts[0].to_string();
    let path = parts[1].to_string();

    // Only allow POST and PUT for uploads
    if method != "POST" && method != "PUT" {
        return Err(ParseError::InvalidRequest);
    }

    // Validate path doesn't contain dangerous sequences
    if path.contains("..") || path.contains("//") {
        return Err(ParseError::InvalidRequest);
    }

    // Parse headers - reject duplicate header names to prevent ambiguity
    let mut headers = HashMap::new();
    loop {
        let mut line = String::new();
        reader.read_line(&mut line).map_err(ParseError::IoError)?;
        let trimmed = line.trim_end_matches(|c| c == '\r' || c == '\n');
        if trimmed.is_empty() {
            break;
        }
        if let Some(colon_pos) = trimmed.find(':') {
            let key = trimmed[..colon_pos].to_string();
            let value = trimmed[colon_pos + 1..].trim().to_string();
            let lower_key = key.to_ascii_lowercase();
            // Reject duplicate Content-Length or Transfer-Encoding headers
            if (lower_key == "content-length" || lower_key == "transfer-encoding")
                && headers.keys().any(|k| k.to_ascii_lowercase() == lower_key) {
                return Err(ParseError::AmbiguousLength);
            }
            headers.insert(key, value);
        }
    }

    // Determine body handling strategy
    let body_length = determine_body_length(&headers)?;

    // Read body
    let body = match body_length {
        BodyLength::Fixed(len) => {
            let mut buf = vec![0u8; len as usize];
            reader.read_exact(&mut buf).map_err(ParseError::IoError)?;
            buf
        }
        BodyLength::Chunked => {
            read_chunked_body(&mut reader)?
        }
    };

    let upload_req = UploadRequest {
        method,
        path,
        headers,
        body,
    };

    // Build and return the normalized request for forwarding
    Ok(build_forwarded_request(&upload_req))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_upload() {
        let request = b"POST /upload/file.bin HTTP/1.1\r\nHost: gateway.example.com\r\nContent-Length: 5\r\n\r\nhello";
        let result = process_upload(request).unwrap();
        let result_str = String::from_utf8_lossy(&result);
        assert!(result_str.contains("Content-Length: 5"));
        assert!(result_str.contains("hello"));
    }

    #[test]
    fn test_chunked_upload() {
        let request = b"POST /upload/file.bin HTTP/1.1\r\nHost: gateway.example.com\r\nTransfer-Encoding: chunked\r\n\r\n5\r\nhello\r\n0\r\n\r\n";
        let result = process_upload(request).unwrap();
        let result_str = String::from_utf8_lossy(&result);
        assert!(result_str.contains("Content-Length: 5"));
    }

    #[test]
    fn test_reject_ambiguous() {
        let request = b"POST /upload/file.bin HTTP/1.1\r\nHost: gateway.example.com\r\nTransfer-Encoding: chunked\r\nContent-Length: 5\r\n\r\nhello";
        let result = process_upload(request);
        assert!(result.is_err());
    }
}
